shader.vertex:
attribute vec3 Position;
attribute vec4 Color;
attribute vec2 TexCoord;
attribute vec4 RenderData;
attribute float Scale;
attribute float Angle;

varying vec4 Color0;
varying vec2 TexCoord0;
varying vec4 RenderDataOut;
varying float ScaleOut;

uniform mat4 Transform;

void main(void)
{
	vec2 pos = Position.xy;
	pos -= RenderData.xy / 4.0;

	float rad = radians(-Angle);
	float cosA = cos(rad);
	float sinA = sin(rad);

	vec2 rotPos;
	rotPos.x = pos.x * cosA - pos.y * sinA;
	rotPos.y = pos.x * sinA + pos.y * cosA;

	rotPos += RenderData.xy / 4.0;

	vec3 finalPos = vec3(rotPos, Position.z);

	Color0 = Color;
	TexCoord0 = TexCoord;
	RenderDataOut = RenderData;
	ScaleOut = Scale;

	gl_Position = Transform * vec4(finalPos, 1.0);
}

shader.fragment:
varying lowp vec4 Color0;
varying mediump vec2 TexCoord0;
varying lowp vec4 RenderDataOut;
varying lowp float ScaleOut;
uniform sampler2D Texture0;
void main(void)
{
	gl_FragColor = Color0 * texture2D(Texture0, TexCoord0);
}
